CREATE OR REPLACE FUNCTION public.static_weekly_assert_projection_envelope_attested(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_legacy jsonb;
  v_snapshot jsonb;
  v_document jsonb;
  v_recurring_source_digest text;
  v_published_source_digest text;
  v_overlay_source_digest text;
begin
  perform public.static_weekly_assert_exact_object(
    p_envelope,
    array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],
    array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],
    'attested projection envelope'
  );
  perform public.static_weekly_assert_authority_attestation(
    p_envelope->'attestation','dated_projection',public.static_weekly_projection_attestation_payload(p_envelope)
  );
  if p_envelope->>'database_projection_identity' is distinct from
     public.static_weekly_digest_jsonb(p_envelope-array['attestation','database_projection_identity']) then
    raise exception using errcode='23514',message='projection semantic identity must bind the complete attested envelope';
  end if;

  v_snapshot:=p_envelope->'semantic_snapshot';
  perform public.static_weekly_assert_exact_object(
    v_snapshot,
    array['schema','recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']||case when p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    array['schema','recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']||case when p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    'projection semantic snapshot'
  );
  if exists(
    select 1
    from unnest(array['recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']) field_name
    where jsonb_typeof(v_snapshot->field_name) is distinct from 'string'
       or coalesce(v_snapshot->>field_name,'') !~ '^[0-9a-f]{64}$'
  ) then
    raise exception using errcode='23514',message='projection semantic snapshot requires exact canonical SHA-256 identities';
  end if;

  select v.draft_document#>'{authority,compilerInput}' into v_document
  from public.weekly_schedule_versions v
  join public.weekly_schedule_publications p on p.version_id=v.version_id
  where p.publication_id=p_publication_id;
  if not found then
    raise exception using errcode='23514',message='projection publication is unknown';
  end if;

  v_recurring_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,compilerInput}')
  );
  v_published_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(v_document)
  );
  v_overlay_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,overlayCompilerInput}')
  );

  if v_snapshot->>'schema' is distinct from (case p_envelope#>>'{adapter,schema}' when 'memphis-zoo.static-weekly-database-adapter.v2' then 'memphis-zoo.static-weekly-projection-semantic-snapshot.v3' else 'memphis-zoo.static-weekly-projection-semantic-snapshot.v2' end)
    or v_snapshot->>'recurring_source_digest' is distinct from v_recurring_source_digest
    or v_snapshot->>'recurring_source_digest' is distinct from v_published_source_digest
    or v_snapshot->>'overlay_source_digest' is distinct from v_overlay_source_digest
    or v_snapshot->>'applied_exceptions_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'applied_exceptions')
    or v_snapshot->>'active_assignments_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'assignments') then
    raise exception using errcode='23514',message='projection must bind stable recurring source, dated staffing and exceptions, and active assignments';
  end if;

  -- The established v4 validator still performs the complete structural,
  -- optimizer, work-snapshot, service-mode, and location checks.  Only the
  -- redundant semantic copies have been replaced by independently recomputed
  -- identities.

  if p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' and (
   v_snapshot->'derived_baseline_digest' is distinct from coalesce(p_envelope#>'{authority,derivedBaselineDigest}',p_envelope#>'{authority,baselineInputDigest}')
   or v_snapshot->'shift_end_derivation_digest' is distinct from to_jsonb(public.static_weekly_digest_jsonb(coalesce(p_envelope#>'{authority,shiftEndDerivation}','null'::jsonb)))) then
   raise exception 'projection snapshot does not bind exact derived baseline'; end if;
  v_legacy:=p_envelope-array['semantic_snapshot','attestation'];
  v_legacy:=jsonb_set(
    v_legacy,'{database_projection_identity}',
    to_jsonb(public.static_weekly_digest_jsonb(v_legacy-'database_projection_identity')),true
  );
  perform public.static_weekly_v4_assert_projection_envelope(
    v_legacy,p_publication_id,p_week_start,p_exception_set
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_create_draft(p_effective_start date, p_objective_version text, p_objective jsonb, p_input_provenance jsonb, p_document jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
declare v_actor jsonb; v_document jsonb; v_response jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); perform public.static_weekly_capacity_source_assert_use(p_source_id,p_manager_id,p_idempotency_key,'draft');
 perform public.place_operational_assert_source_use(p_source_id,p_manager_id,p_idempotency_key,'draft');
  perform public.static_weekly_v14_assert_recurring_source_use(p_source_id,p_manager_id,p_effective_start,p_idempotency_key,'draft'); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); perform public.static_weekly_v3_assert_registered_source(p_source_id,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',p_effective_start,true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
  v_response:=public.static_weekly_v2_create_draft(p_effective_start,p_objective_version,p_objective,p_input_provenance,v_document,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
  v_version:=(v_response#>>'{data,version_id}')::uuid; perform set_config('app.static_weekly_source_bind','on',true); update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version and authority_source_id is null;
  select authority_source_id into v_source from public.weekly_schedule_versions where version_id=v_version for share;
  if v_source is distinct from p_source_id then raise exception using errcode='23514',message='draft did not retain one immutable authority source identity'; end if;
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_update_draft(p_version_id uuid, p_document jsonb, p_objective jsonb, p_input_provenance jsonb, p_expected_draft_revision bigint, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
declare v_actor jsonb; v_document jsonb; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.static_weekly_v14_assert_recurring_source_use((select authority_source_id from public.weekly_schedule_versions where version_id=p_version_id),p_manager_id,null,p_idempotency_key,'update'); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); select authority_source_id into v_source from public.weekly_schedule_versions where version_id=p_version_id and lifecycle_state='draft' for share; perform public.static_weekly_v3_assert_registered_source(v_source,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',(select effective_start from public.weekly_schedule_versions where version_id=p_version_id),true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
  return public.static_weekly_v2_update_draft(p_version_id,v_document,p_objective,p_input_provenance,p_expected_draft_revision,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_assert_lunch_document(p_projection_id uuid, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 projection public.weekly_schedule_compiled_projections%rowtype;
 loan jsonb;responsibility jsonb;segment jsonb;intent jsonb;availability jsonb;helper jsonb;
 base_work jsonb;expected jsonb;actual jsonb;helper_id text;identity_key text;
 start_time time;end_time time;
 projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;
 full_hour_policy jsonb;full_hour boolean;planned_loan jsonb;normal_segment_window jsonb;
begin
 perform public.static_weekly_assert_exact_object(p_document,
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],'lunch document');
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=p_projection_id;
 if not found then raise exception 'lunch projection is missing'; end if;

 projection_availability:=projection.projection_envelope#>'{authority,projectionAvailability}';
 projection_assignments:=projection.projection_envelope->'assignments';
 projection_work:=projection.projection_envelope#>'{authority,overlayCompilerInput,version,assignments}';
 full_hour_policy:=projection.projection_envelope#>'{authority,compilerInput,version,lunchCoveragePolicy}';
 full_hour:=full_hour_policy is not null;
 if projection.projection_envelope#>'{authority,overlayCompilerInput,version,lunchCoveragePolicy}'
   is distinct from full_hour_policy then raise exception 'full lunch policy changed during projection';end if;
 if full_hour then
  perform public.static_weekly_assert_exact_object(full_hour_policy,
   array['schema','sourceDigest','loans','policyDigest'],array['schema','sourceDigest','loans','policyDigest'],'full lunch policy');
  if full_hour_policy->>'schema' is distinct from 'memphis-zoo.static-weekly-full-hour-lunch-policy.v1'
   or jsonb_typeof(full_hour_policy->'sourceDigest') is distinct from 'string'
   or coalesce(full_hour_policy->>'sourceDigest','') !~ '^[0-9a-f]{64}$'
   or full_hour_policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(full_hour_policy-'policyDigest')
   or jsonb_typeof(full_hour_policy->'loans') is distinct from 'array'
   or jsonb_array_length(full_hour_policy->'loans')>1792 then raise exception 'invalid full lunch source policy';end if;
  for planned_loan in select value from jsonb_array_elements(full_hour_policy->'loans') loop
   perform public.static_weekly_assert_exact_object(planned_loan,
    array['dayOfWeek','normalOwnerSlotId','window','areas'],array['dayOfWeek','normalOwnerSlotId','window','areas'],'full lunch source loan');
   perform public.static_weekly_v3_assert_window(planned_loan->'window','full lunch source window');
   if jsonb_typeof(planned_loan->'dayOfWeek') is distinct from 'number'
    or (planned_loan->>'dayOfWeek') !~ '^[0-6]$'
    or jsonb_typeof(planned_loan->'normalOwnerSlotId') is distinct from 'string'
    or length(planned_loan->>'normalOwnerSlotId') not between 1 and 512
    or jsonb_typeof(planned_loan->'areas') is distinct from 'array'
    or jsonb_array_length(planned_loan->'areas')>128 then raise exception 'invalid full lunch source owner or areas';end if;
  end loop;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into expected from
   (select jsonb_build_array(value->'dayOfWeek',value->'normalOwnerSlotId') entry
    from jsonb_array_elements(full_hour_policy->'loans')) q;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into actual from
   (select jsonb_build_array(value->'day_of_week',value->'normal_owner_slot_id') entry
    from jsonb_array_elements(p_document->'loans')) q;
  if expected is distinct from actual then raise exception 'full lunch source owner set changed';end if;
 end if;

 if p_document->>'schema' is distinct from 'memphis-zoo.static-weekly-lunch-authority-document.v1'
  or p_document->>'persistence_authority' is distinct from 'NOT_PERSISTED'
  or p_document->>'verification_status' is distinct from 'VERIFIED'
  or p_document->>'week_start' is distinct from projection.week_start::text
  or p_document->>'base_authority_digest' is distinct from projection.authority_digest
  or p_document->>'base_replay_digest' is distinct from projection.replay_digest
  or p_document->>'source_input_digest' is distinct from projection.projection_envelope#>>'{authority,inputDigest}'
  or coalesce(p_document->>'candidate_digest','') !~ '^[0-9a-f]{64}$'
  or p_document->>'document_identity' is distinct from public.static_weekly_digest_jsonb(p_document-'document_identity') then
  raise exception 'lunch document is not bound to the exact verified projection';
 end if;
 foreach identity_key in array array['loans','responsibilities','notification_intents'] loop
  if jsonb_typeof(p_document->identity_key) is distinct from 'array'
   or jsonb_array_length(p_document->identity_key)>4096 then raise exception 'lunch document array invalid'; end if;
 end loop;
 expected:=jsonb_build_object('schema','memphis-zoo.static-weekly-lunch-semantic-snapshot.v1',
  'loans_digest',public.static_weekly_digest_jsonb(p_document->'loans'),
  'responsibilities_digest',public.static_weekly_digest_jsonb(p_document->'responsibilities'),
  'notification_intents_digest',public.static_weekly_digest_jsonb(p_document->'notification_intents'));
 if p_document->'semantic_snapshot' is distinct from expected then raise exception 'lunch semantic snapshot mismatch'; end if;
 if (select count(*)<>count(distinct value->>'loan_id') from jsonb_array_elements(p_document->'loans'))
 or (select count(*)<>count(distinct value->>'responsibility_id') from jsonb_array_elements(p_document->'responsibilities'))
 or (select count(*)<>count(distinct value->>'notification_key') from jsonb_array_elements(p_document->'notification_intents')) then
  raise exception 'duplicate or missing lunch record identity'; end if;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'serviceDate',value->>'slotId') order by value->>'serviceDate',value->>'slotId'),'[]')
 into expected from jsonb_array_elements(projection_availability)
 where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY')
  and (value->>'ownerKind'='CONTRACTOR_CAPACITY' and value->>'breakChoice'='NONE' and value->'lunch'='null'::jsonb) is not true;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'service_date',value->>'normal_owner_slot_id') order by value->>'service_date',value->>'normal_owner_slot_id'),'[]')
 into actual from jsonb_array_elements(p_document->'loans');
 if actual is distinct from expected then raise exception 'lunch coverage omits or duplicates a working owner'; end if;
 for loan in select value from jsonb_array_elements(p_document->'loans') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,loan,'normal_owner');
  perform public.static_weekly_assert_exact_object(loan,
   case when loan ? 'normal_owner_capacity_id' then array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_capacity_id','coverage_start','coverage_end','status','helper_slot_ids']
    else array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end','status','helper_slot_ids'] end,
   array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverage_start','coverage_end','status','reason','helper_slot_ids','fallback','total_distance_minutes'],'lunch loan');
  if not (loan ?& array['reason','fallback','total_distance_minutes']) then raise exception 'lunch explanatory fields are missing'; end if;
  if coalesce(loan->>'loan_id','') !~ '^[0-9a-f]{64}$' then raise exception 'invalid lunch loan identity'; end if;
  select value into availability from jsonb_array_elements(projection_availability)
   where value->>'slotId'=loan->>'normal_owner_slot_id' and value->>'serviceDate'=loan->>'service_date';
  if not found or availability->>'incumbentPersonId' is distinct from loan->>'normal_owner_person_id'
   or loan->'day_of_week' is distinct from availability->'dayOfWeek'
   or loan->>'coverage_start' is distinct from availability#>>'{lunch,start}'
   or loan->>'coverage_end' is distinct from availability#>>'{lunch,end}' then raise exception 'lunch owner or scheduled hour mismatch'; end if;
  perform public.static_weekly_v3_assert_window(jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end'),'lunch');
  start_time:=(loan->>'coverage_start')::time;end_time:=(loan->>'coverage_end')::time;
  if end_time<=start_time then raise exception 'accepted lunch end must follow its start'; end if;
  perform public.static_weekly_v3_assert_string_array(loan->'helper_slot_ids','lunch helpers');
  if ((loan->>'status'='NO_AREAS' and jsonb_array_length(loan->'helper_slot_ids')=0 and loan->'fallback'='null'::jsonb)
    or (loan->>'status'='PLANNED' and ((jsonb_array_length(loan->'helper_slot_ids')=2 and loan->'fallback'='null'::jsonb)
      or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))) is not true then
   raise exception 'lunch helper cardinality or fallback invalid'; end if;
  if full_hour then
   select value into strict planned_loan from jsonb_array_elements(full_hour_policy->'loans')
    where value->'dayOfWeek'=loan->'day_of_week' and value->'normalOwnerSlotId'=loan->'normal_owner_slot_id';
   if planned_loan->'window' is distinct from jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end')
    then raise exception 'full lunch source window changed';end if;
  end if;
  for helper_id in select jsonb_array_elements_text(loan->'helper_slot_ids') loop
   select value into helper from jsonb_array_elements(projection_availability)
    where value->>'slotId'=helper_id and value->>'serviceDate'=loan->>'service_date';
   if not found or helper->>'status' is distinct from 'working' or helper_id=loan->>'normal_owner_slot_id'
    or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY')
    or ((helper#>>'{lunch,start}' is null or helper#>>'{lunch,end}' is null)
      and (helper->>'ownerKind'='CONTRACTOR_CAPACITY' and helper->>'breakChoice'='NONE' and helper->'lunch'='null'::jsonb) is not true) or (helper#>>'{shift,start}')::time>start_time
    or (helper#>>'{shift,end}')::time<end_time
    or ((helper#>>'{lunch,start}')::time<end_time and start_time<(helper#>>'{lunch,end}')::time) then
    raise exception 'lunch helper is not available for the full scheduled hour'; end if;
   if not exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r
     where r->>'loan_id'=loan->>'loan_id' and r->>'coverer_slot_id'=helper_id) then
    raise exception 'lunch helper has no assigned responsibility'; end if;
  end loop;
 end loop;
 for responsibility in select value from jsonb_array_elements(p_document->'responsibilities') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'normal_owner');
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'coverer');
  perform public.static_weekly_assert_exact_object(responsibility,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','coverer_slot_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments']
    ||case when responsibility ? 'normal_owner_capacity_id' then array['normal_owner_capacity_id'] else array['normal_owner_person_id'] end
    ||case when responsibility ? 'coverer_capacity_id' then array['coverer_capacity_id'] else array['coverer_person_id'] end,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverer_slot_id','coverer_person_id','coverer_capacity_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments'],'lunch responsibility');
  select value into loan from jsonb_array_elements(p_document->'loans') where value->>'loan_id'=responsibility->>'loan_id';
  if not found or loan->>'status'<>'PLANNED' then raise exception 'lunch responsibility has no planned loan'; end if;
  foreach identity_key in array array['service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end'] loop
   if responsibility->identity_key is distinct from loan->identity_key then raise exception 'lunch responsibility scope mismatch'; end if;
  end loop;
  select value into helper from jsonb_array_elements(projection_availability)
   where value->>'slotId'=responsibility->>'coverer_slot_id' and value->>'serviceDate'=responsibility->>'service_date';
  if not found or helper->>'incumbentPersonId' is distinct from responsibility->>'coverer_person_id'
   or not (loan->'helper_slot_ids' ? (responsibility->>'coverer_slot_id'))
   or coalesce(responsibility->>'responsibility_id','') !~ '^[0-9a-f]{64}$'
   or responsibility->>'coverage_purpose' is distinct from 'lunch_coverage'
   or responsibility->>'check_deadline_policy' is distinct from 'inherit_existing_90_minute_deadline'
   or responsibility->'creates_deep_clean' is distinct from 'false'::jsonb
   or jsonb_typeof(responsibility->'segments') is distinct from 'array'
   or jsonb_array_length(responsibility->'segments')=0 then raise exception 'lunch responsibility policy or recipient mismatch'; end if;
  for segment in select value from jsonb_array_elements(responsibility->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['planWorkId','workId','serviceMode','window','includedLocations']||case when full_hour then array['normalWindow'] else array[]::text[] end,
    array['planWorkId','workId','serviceMode','window','includedLocations']||case when full_hour then array['normalWindow'] else array[]::text[] end,'lunch segment');
   select value into base_work from jsonb_array_elements(projection_assignments)
    where value->>'plan_work_id'=segment->>'planWorkId' and value->>'service_date'=responsibility->>'service_date';
   if not found or base_work->>'status' is distinct from 'assigned'
    or base_work->>'owner_slot_id' is distinct from responsibility->>'normal_owner_slot_id'
    or base_work->>'owner_person_id' is distinct from responsibility->>'normal_owner_person_id'
    or base_work->>'work_id' is distinct from segment->>'workId'
    or base_work#>'{work_snapshot,includedLocations}' is distinct from segment->'includedLocations'
    or base_work#>>'{work_snapshot,serviceMode}' is distinct from segment->>'serviceMode'
    or segment->>'serviceMode'='reminder_only' then raise exception 'borrowed area differs from original assignment'; end if;
   if not ((helper->'qualifications') @> (base_work#>'{work_snapshot,requiredQualifications}'))
    or (base_work#>'{work_snapshot,restrictedSlotIds}') ? (responsibility->>'coverer_slot_id')
    or exists(select 1 from jsonb_array_elements(segment->'includedLocations') location
      where helper->'restrictions' ? (location->>'locationId')) then
    raise exception 'lunch helper is restricted or unqualified for a borrowed area'; end if;
   perform public.static_weekly_v3_assert_window(segment->'window','borrowed area');
   normal_segment_window:=case when full_hour then segment->'normalWindow' else segment->'window' end;
   perform public.static_weekly_v3_assert_window(normal_segment_window,'original borrowed-area anchor');
   if (normal_segment_window->>'start')::time<>greatest((base_work#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time)
    or (normal_segment_window->>'end')::time<>least((base_work#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time) then
    raise exception 'borrowed-area window must be the exact normal-duty and lunch intersection'; end if;
   if full_hour then
    if segment->'window' is distinct from jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end')
     then raise exception 'full lunch area must cover the entire accepted lunch';end if;
    select value into strict planned_loan from jsonb_array_elements(full_hour_policy->'loans')
     where value->'dayOfWeek'=loan->'day_of_week' and value->'normalOwnerSlotId'=loan->'normal_owner_slot_id';
    if not exists(select 1 from jsonb_array_elements(planned_loan->'areas') area
     where area->>'locationCode'=base_work#>>'{work_snapshot,locationCodeSnapshot}'
      and area->'covererSlotId'=responsibility->'coverer_slot_id') then
     raise exception 'full lunch recipient differs from the immutable area plan';end if;
   end if;
  end loop;
 end loop;
 if full_hour then
  for planned_loan in select value from jsonb_array_elements(full_hour_policy->'loans') loop
   for segment in select value from jsonb_array_elements(planned_loan->'areas') loop
    perform public.static_weekly_assert_exact_object(segment,array['locationCode','covererSlotId'],array['locationCode','covererSlotId'],'full lunch source area');
    if jsonb_typeof(segment->'locationCode') is distinct from 'string' or length(segment->>'locationCode') not between 1 and 512
     or jsonb_typeof(segment->'covererSlotId') is distinct from 'string' or length(segment->>'covererSlotId') not between 1 and 512
     or segment->'covererSlotId'=planned_loan->'normalOwnerSlotId' then raise exception 'invalid full lunch source area';end if;
   end loop;
  end loop;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into expected from
   (select jsonb_build_array(l->'dayOfWeek',l->'normalOwnerSlotId',a->'locationCode',a->'covererSlotId') entry
    from jsonb_array_elements(full_hour_policy->'loans') l cross join lateral jsonb_array_elements(l->'areas') a) q;
  select coalesce(jsonb_agg(entry order by entry::text),'[]') into actual from
   (select distinct jsonb_build_array(r->'day_of_week',r->'normal_owner_slot_id',a#>'{work_snapshot,locationCodeSnapshot}',r->'coverer_slot_id') entry
    from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s
    join jsonb_array_elements(projection_assignments) a on a->>'plan_work_id'=s->>'planWorkId'
     and a->'service_date'=r->'service_date') q;
  if expected is distinct from actual then raise exception 'full lunch source areas omitted, duplicated or reassigned';end if;
  if exists(with areas as materialized (
    select r->>'service_date' service_date,loc->>'locationId' location_id,
     jsonb_build_array(r->'coverer_slot_id',r->'coverer_person_id',r->'coverer_capacity_id') recipient,
     (s#>>'{window,start}')::time starts,(s#>>'{window,end}')::time ends
    from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s
     cross join lateral jsonb_array_elements(s->'includedLocations') loc)
   select 1 from areas a join areas b on a.service_date=b.service_date and a.location_id=b.location_id
    and a.recipient is distinct from b.recipient and a.starts<b.ends and b.starts<a.ends) then
   raise exception 'full lunch plans conflict on current physical responsibility';end if;
 end if;
 -- Account for every normal flexible duty that intersects each scheduled lunch.
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',a->>'plan_work_id')
  order by l->>'loan_id',a->>'plan_work_id'),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l
 join jsonb_array_elements(projection_assignments) a
  on a->>'service_date'=l->>'service_date' and a->>'owner_slot_id'=l->>'normal_owner_slot_id'
 join jsonb_array_elements(projection_work) w
  on w->>'workId'=a->>'work_id' and w->>'dayOfWeek'=a->>'day_of_week'
 where a->>'status'='assigned' and w->>'schedulingMode'='flexible_coverage_ownership'
  and w->>'serviceMode'<>'reminder_only'
  and (a#>>'{work_snapshot,window,start}')::time<(l->>'coverage_end')::time
  and (l->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time;
 select coalesce(jsonb_agg(jsonb_build_array(r->>'loan_id',s->>'planWorkId')
  order by r->>'loan_id',s->>'planWorkId'),'[]') into actual
 from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s;
 if actual is distinct from expected then raise exception 'lunch responsibility must cover every eligible original area exactly once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s group by r->>'loan_id',s->>'planWorkId' having count(*)>1) then
  raise exception 'borrowed work assigned more than once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s,jsonb_array_elements(s->'includedLocations') location
  group by r->>'loan_id',location->>'locationId' having count(distinct r->>'coverer_slot_id')>1) then
  raise exception 'paired or grouped locations split between lunch helpers'; end if;
 for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop
  perform public.static_weekly_assert_exact_object(intent,
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],'lunch notification intent');
  if coalesce(intent->>'notification_key','') !~ '^[0-9a-f]{64}$'
   or intent->>'delivery_state' is distinct from 'NOT_ENQUEUED' then raise exception 'invalid lunch notification intent'; end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',l->>'service_date',h,e,
  case e when 'start' then l->>'coverage_start' else l->>'coverage_end' end) order by l->>'loan_id',h,e),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l cross join lateral jsonb_array_elements_text(l->'helper_slot_ids') h
 cross join unnest(array['start','end']) e
 where exists(select 1 from jsonb_array_elements(projection_availability) a
  where a->>'slotId'=h and a->>'serviceDate'=l->>'service_date' and nullif(a->>'incumbentPersonId','') is not null);
 select coalesce(jsonb_agg(jsonb_build_array(n->>'loan_id',n->>'service_date',n->>'coverer_slot_id',n->>'event',n->>'scheduled_time')
  order by n->>'loan_id',n->>'coverer_slot_id',n->>'event'),'[]') into actual
 from jsonb_array_elements(p_document->'notification_intents') n;
 if actual is distinct from expected then raise exception 'lunch start/end intents must exactly cover every helper'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_assert_shift_end_derivation(p_authority jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
 SET plan_cache_mode TO 'force_generic_plan'
AS $function$
declare
 source jsonb:=p_authority->'compilerInput';
 effective jsonb:=jsonb_set(p_authority->'overlayCompilerInput','{exceptions}','[]'::jsonb);
 policy jsonb:=source#>'{version,shiftEndContinuityPolicy}';
 receipt jsonb:=p_authority->'shiftEndDerivation';
 roster jsonb; boundaries jsonb; chain jsonb; parent jsonb; segment jsonb; work jsonb;
 person jsonb; owner jsonb; physical jsonb; key text; previous_end text; final_end text;
 day integer; matches integer; total numeric; seen text[]:='{}'; parent_seen text[]:='{}';
 minute_samples integer:=0; location_samples integer:=0; location_count integer; span integer;
 planned_day text;planned_stages jsonb;planned_stage jsonb;planned_parent jsonb;planned_person jsonb;planned_availability jsonb;planned_families jsonb;planned_previous time;planned_last time;planned_start time;planned_end time;planned_coverage interval;planned_valid_edges jsonb;
 named jsonb; named_parent jsonb; named_chain jsonb; named_from jsonb; named_to jsonb; named_to_availability jsonb;
 named_parent_id text; named_key text; named_seen text[]:='{}';
begin
 perform public.static_weekly_assert_exact_object(policy,
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest'],
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest','namedHandoffs','plannedClosingOwnership'],'shift-end source policy');
 if policy ? 'namedHandoffs' then
  if jsonb_typeof(policy->'namedHandoffs') is distinct from 'array' then
   raise exception using errcode='23514',message='shift-end named handoffs must be one array';
  end if;
  if jsonb_array_length(policy->'namedHandoffs')>14 then
   raise exception using errcode='23514',message='shift-end named handoffs exceed the source bound';
  end if;
 end if;
 perform public.static_weekly_assert_exact_object(receipt,
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],'shift-end derivation receipt');
 if policy->>'schema' is distinct from 'memphis-zoo.shift-end-continuity-policy.v1'
  or policy->>'algorithm' is distinct from 'dated-real-staff-directed-proximity-weighted-v1'
  or policy->>'normalPhaseStart' is distinct from '09:45'
  or coalesce(policy->>'provenance','') !~ '^owner-configuration-sha256:[a-f0-9]{64}$'
  or policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(policy-'policyDigest')
  or receipt->>'schema' is distinct from 'memphis-zoo.shift-end-derivation.v1'
  or receipt->>'algorithm' is distinct from policy->>'algorithm'
  or receipt->>'policyDigest' is distinct from policy->>'policyDigest'
  or receipt->>'templateDigest' is distinct from public.static_weekly_digest_jsonb(source)
  or receipt->>'derivedBaselineDigest' is distinct from public.static_weekly_digest_jsonb(effective)
  or receipt->>'derivedBaselineDigest' is distinct from p_authority->>'derivedBaselineDigest'
  or source->'exceptions' is distinct from '[]'::jsonb
  or source#>'{version,shiftEndDerivationApplied}' is not null
  or effective#>>'{version,shiftEndDerivationApplied}' is distinct from policy->>'policyDigest'
  or source-'version' is distinct from effective-'version'
  or (source->'version')-'assignments' is distinct from (effective->'version')-'assignments'-'shiftEndDerivationApplied'
  or jsonb_typeof(policy->'weights') is distinct from 'object'
  or jsonb_typeof(source#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(effective#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(receipt->'parentChains') is distinct from 'array'
  or jsonb_array_length(source#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(effective#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(receipt->'parentChains')<>jsonb_array_length(source#>'{version,assignments}')
  or receipt->>'outputWorkDigest' is distinct from public.static_weekly_digest_jsonb(effective#>'{version,assignments}') then
  raise exception using errcode='23514',message='shift-end source, policy, derived baseline and receipt identities must be exact';
 end if;
 if exists(select 1 from jsonb_each(policy->'weights') w where jsonb_typeof(w.value)<>'number'
  or (w.value#>>'{}')::numeric<=0 or (w.value#>>'{}')::numeric>1000
  or (w.value#>>'{}')::numeric*2<>trunc((w.value#>>'{}')::numeric*2)) then
  raise exception using errcode='23514',message='shift-end weights require exact positive bounded half units';
 end if;
 -- Derive this roster from immutable availability plus dated incumbent ranges,
 -- never from exception-mutated projectionAvailability or a caller roster blob.
 with facts as (
  select a, s, (source->>'serviceDate')::date+
   mod((a->>'dayOfWeek')::int-extract(dow from (source->>'serviceDate')::date)::int+7,7) d
  from jsonb_array_elements(source#>'{version,slotAvailability}') a
  join jsonb_array_elements(source->'slots') s on s->>'id'=a->>'slotId'
  where coalesce(s->'contractorCapacity','false'::jsonb)='false'::jsonb
 ), dated as (
  select *, (select count(*) from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date)) n,
   (select i from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date) limit 1) incumbent
  from facts
 ) select coalesce(jsonb_agg(jsonb_build_object('serviceDate',d::text,'dayOfWeek',a->'dayOfWeek',
   'slotId',a->'slotId','personId',incumbent->'personId','vacant',n=0,'status',a->'status',
   'shift',a->'shift','lunch',a->'lunch') order by (a->>'dayOfWeek')::int,a->>'slotId'),'[]'::jsonb),
  count(*) filter(where n>1 or (n=0 and not coalesce((source#>'{version,vacancyCapableSlotIds}') ? (a->>'slotId'),false))
   or (n=0) is distinct from (a->>'status'='vacant_unfilled')
   or a->>'status' not in ('working','vacant_unfilled','departed_named_absent'))
 into roster,matches from dated;
 if matches<>0 or jsonb_array_length(roster)=0
  or (select count(*) from jsonb_array_elements(roster))<>(select count(distinct (r->>'dayOfWeek',r->>'slotId')) from jsonb_array_elements(roster) r)
  or receipt->>'datedRosterDigest' is distinct from public.static_weekly_digest_jsonb(roster) then
  raise exception using errcode='23514',message='shift-end receipt must bind one exact dated real roster';
 end if;
 select jsonb_object_agg(d::text,closing) into boundaries from (
  select (r->>'dayOfWeek')::int d,max(r#>>'{shift,end}') closing from jsonb_array_elements(roster) r
  where r->'vacant'='false'::jsonb and r->>'status'='working' group by 1
 ) endings;
 if boundaries is null or (select count(*) from jsonb_object_keys(boundaries))<>7
  or boundaries is distinct from receipt->'staffedDepartureByDay' then
  raise exception using errcode='23514',message='shift-end boundary requires real working incumbent on every day';
 end if;
 for chain in select value from jsonb_array_elements(receipt->'parentChains') loop
  perform public.static_weekly_assert_exact_object(chain,
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],'shift-end parent chain');
  day:=(chain->>'dayOfWeek')::int; key:=day::text||':'||(chain->>'parentWorkId');
  select count(*) into matches from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  if matches<>1 or key=any(parent_seen) then raise exception 'shift-end parent must exist exactly once'; end if;
  parent_seen:=array_append(parent_seen,key);
  select w into parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  select jsonb_object_agg(k,coalesce(parent->k,'null'::jsonb)) into physical from unnest(array[
   'locationId','locationCodeSnapshot','locationNameSnapshot','includedLocations','serviceMode','requiredQualifications',
   'restrictedSlotIds','restrictions','qualificationProvenance','restrictionProvenance']) k;
  if chain->>'physicalIdentityDigest' is distinct from public.static_weekly_digest_jsonb(physical)
   or chain->'workloadBefore' is distinct from parent->'serviceEffortMinutes'
   or chain->'workloadAfter' is distinct from parent->'serviceEffortMinutes'
   or jsonb_typeof(chain->'segments') is distinct from 'array' or jsonb_array_length(chain->'segments')<1
   or position(':handoff:' in parent->>'workId')>0 or position(':open:' in parent->>'workId')>0 then
   raise exception 'shift-end chain must retain exact immutable parent identity and workload';
  end if;
  previous_end:=parent#>>'{window,start}';final_end:=boundaries->>day::text;total:=0;
  if previous_end='09:45' then
   select r into owner from jsonb_array_elements(roster) r where r->>'slotId'=parent->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
   if not found or parent#>>'{window,end}' is distinct from owner#>>'{shift,end}'
    or parent->'originSlotId' is distinct from parent->'ownerSlotId'
    or not ((policy->'weights') ? (parent->>'locationCodeSnapshot')) then
    raise exception 'immutable normal parent must retain full owning position shift and weight'; end if;
  end if;
  for segment in select value from jsonb_array_elements(chain->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],'shift-end segment');
   key:=day::text||':'||(segment->>'workId');
   select count(*) into matches from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   if matches<>1 or key=any(seen) then raise exception 'derived segment must occur exactly once'; end if;
   seen:=array_append(seen,key);
   select w into work from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   perform public.static_weekly_v3_assert_window(segment->'window','shift-end segment');
   if segment#>>'{window,start}' is distinct from previous_end
    or segment->'window' is distinct from work->'window'
    or segment->'ownerSlotId' is distinct from work->'ownerSlotId'
    or segment->'serviceEffortMinutes' is distinct from work->'serviceEffortMinutes'
    or jsonb_typeof(segment->'serviceEffortMinutes') is distinct from 'number'
    or (segment->>'serviceEffortMinutes')::numeric<=0
    or (segment->>'serviceEffortMinutes')::numeric<>trunc((segment->>'serviceEffortMinutes')::numeric)
    or (work-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
       is distinct from (parent-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
    or work->'ownerSlotId' is distinct from work->'originSlotId'
    or work->>'serviceEffortProvenance' is distinct from ((parent->>'serviceEffortProvenance')||
       case when jsonb_array_length(chain->'segments')>1 then ';shift-split-preserves-budget' else '' end) then
    raise exception 'derived segment changed immutable work, exact workload or contiguous window';
   end if;
   previous_end:=segment#>>'{window,end}';total:=total+(segment->>'serviceEffortMinutes')::numeric;
   if parent#>>'{window,start}'<>'09:45' then
    if work is distinct from parent or segment->>'kind' is distinct from 'baseline' then raise exception 'non-closing work must be unchanged'; end if;
   else
    select r into person from jsonb_array_elements(roster) r where r->>'slotId'=work->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
    select a into owner from jsonb_array_elements(source#>'{version,slotAvailability}') a where a->>'slotId'=work->>'ownerSlotId' and a->>'dayOfWeek'=day::text;
    if person is null or owner is null or work#>>'{window,start}'<person#>>'{shift,start}'
     or previous_end>person#>>'{shift,end}' or previous_end>final_end
     or (work->'restrictedSlotIds') ? (work->>'ownerSlotId')
     or not ((owner->'qualifications') @> (work->'requiredQualifications'))
     or exists(select 1 from jsonb_array_elements(work->'includedLocations') loc where (owner->'restrictions') ? (loc->>'locationId')) then
     raise exception 'derived normal responsibility has off-duty or ineligible position'; end if;
    if segment->>'kind'='baseline' then
     if work->'workId' is distinct from parent->'workId' or work->'ownerSlotId' is distinct from parent->'ownerSlotId' then raise exception 'baseline segment identity changed'; end if;
    elsif segment->>'kind' in ('open','handoff') then
     if work->>'workId' is distinct from (parent->>'workId')||':'||(segment->>'kind')||':'||(work#>>'{window,start}')||':'||(work->>'ownerSlotId')
      or (segment->>'kind'='open') is distinct from (person->'vacant'='true'::jsonb)
      or (segment->>'kind'='handoff' and (person->>'status'<>'working' or person->>'personId' is null))
      or (person#>>'{lunch,start}'<=work#>>'{window,start}' and work#>>'{window,start}'<person#>>'{lunch,end}') then
      raise exception 'physical handoff or explicit OPEN segment identity invalid'; end if;
    else raise exception 'unknown derived segment kind'; end if;
   end if;
  end loop;
  if total<>(parent->>'serviceEffortMinutes')::numeric
   or (parent#>>'{window,start}'='09:45' and previous_end is distinct from final_end) then
   raise exception 'parent chain must conserve workload and reach final staffed boundary'; end if;
 end loop;
 if cardinality(seen)<>jsonb_array_length(effective#>'{version,assignments}') then raise exception 'unaccounted derived work'; end if;

 -- A policy string alone never authorizes a new recipient. Every named
 -- handoff must occur exactly once in the already-validated immutable
 -- parent chain, at the departing source worker's actual shift end, with a
 -- real eligible/on-duty recipient and all required directed edges. The
 -- accepted six-key historical policy follows this block without change.
 for named in select value from jsonb_array_elements(coalesce(policy->'namedHandoffs','[]'::jsonb)) loop
  perform public.static_weekly_assert_exact_object(named,
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],'shift-end named handoff');
  if (jsonb_typeof(named->'dayOfWeek')='number'
    and named->>'dayOfWeek' ~ '^[0-6]$'
    and jsonb_typeof(named->'locationCode')='string'
    and (policy->'weights') ? (named->>'locationCode')
    and jsonb_typeof(named->'at')='string'
    and named->>'at' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    and jsonb_typeof(named->'fromSlotId')='string'
    and named->>'fromSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and jsonb_typeof(named->'toSlotId')='string'
    and named->>'toSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and named->>'fromSlotId'<>named->>'toSlotId'
    and jsonb_typeof(named->'source')='string'
    and length(named->>'source') between 10 and 300) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff typed source identity invalid';
  end if;
  named_key:=(named->>'dayOfWeek')||':'||(named->>'locationCode')||':'||(named->>'at');
  if named_key=any(named_seen) then
   raise exception using errcode='23514',message='shift-end named handoff duplicated';
  end if;
  named_seen:=array_append(named_seen,named_key);
  select count(*),max(w->>'workId') into matches,named_parent_id
   from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek'
    and w->>'locationCodeSnapshot'=named->>'locationCode'
    and w#>>'{window,start}'='09:45';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named parent source is not unique';
  end if;
  select w into named_parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'workId'=named_parent_id;
  select c into named_chain from jsonb_array_elements(receipt->'parentChains') c
   where c->>'dayOfWeek'=named->>'dayOfWeek' and c->>'parentWorkId'=named_parent_id;
  if named_chain is null then
   raise exception using errcode='23514',message='shift-end named parent chain absent';
  end if;
  select count(*) into matches
   from jsonb_array_elements(named_chain->'segments') with ordinality as s(segment,ordinal)
   where s.ordinal>1 and s.segment->>'kind'='handoff'
    and s.segment#>>'{window,start}'=named->>'at'
    and s.segment->>'ownerSlotId'=named->>'toSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))->>'ownerSlotId'=named->>'fromSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))#>>'{window,end}'=named->>'at';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named handoff does not match exactly one derived segment';
  end if;
  select r into named_from from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'fromSlotId';
  select r into named_to from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'toSlotId';
  select a into named_to_availability from jsonb_array_elements(source#>'{version,slotAvailability}') a
   where a->>'dayOfWeek'=named->>'dayOfWeek' and a->>'slotId'=named->>'toSlotId';
  if (named_from->>'status'='working' and named_from->>'personId' is not null
    and named_from#>>'{shift,end}'=named->>'at'
    and named_to->>'status'='working' and named_to->>'personId' is not null
    and named_to#>>'{shift,start}'<=named->>'at'
    and named->>'at'<named_to#>>'{shift,end}'
    and not (named_to#>>'{lunch,start}'<=named->>'at' and named->>'at'<named_to#>>'{lunch,end}')
    and (named_to_availability->'qualifications') @> (named_parent->'requiredQualifications')
    and not ((named_parent->'restrictedSlotIds') ? (named->>'toSlotId'))
    and not exists(select 1 from jsonb_array_elements(case
      when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
      else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) target
      where (named_to_availability->'restrictions') ? (target->>'locationId'))
  ) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff source or recipient is not current and eligible';
  end if;
  -- The JS source-derived selector requires a verified directed edge from
  -- at least one exact current-source target-position anchor to every member.
  -- Normal owned members take precedence; only a position owning no normal
  -- row may use its explicit accepted route anchor.
  with anchors as (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
    cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0
      then w->'includedLocations' else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
    where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
     and w#>>'{window,start}'='09:45'
   union all
   select named_to_availability->>'acceptedRouteAnchorLocationId'
    where not exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') w
      where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
       and w#>>'{window,start}'='09:45')
  ), targets as (
   select l->>'locationId' id from jsonb_array_elements(case
     when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) l
  )
  select count(*) into matches from targets target where not exists(
   select 1 from anchors anchor where anchor.id is not null and
    (anchor.id=target.id or exists(select 1 from jsonb_array_elements(source->'proximity') edge
      where edge->>'fromLocationId'=anchor.id and edge->>'toLocationId'=target.id
       and edge->'verified'='true'::jsonb and jsonb_typeof(edge->'minutes')='number'
       and (edge->>'minutes')::numeric>=0 and (edge->>'minutes')::numeric=trunc((edge->>'minutes')::numeric)
       and nullif(edge->>'provenance','') is not null)));
  if matches<>0 then
   raise exception using errcode='23514',message='shift-end named handoff lacks verified directed source proximity';
  end if;
 end loop;
 if policy ? 'plannedClosingOwnership' then
  if jsonb_typeof(policy->'plannedClosingOwnership') is distinct from 'object'
   or (select jsonb_agg(k order by k) from jsonb_object_keys(policy->'plannedClosingOwnership') k)
     is distinct from '["0","1","2","3","4","5","6"]'::jsonb then
   raise exception 'planned closing source must bind all seven days';end if;
  -- Index the same verified directed edges once. Expanding the complete
  -- proximity graph again for every inherited physical member needlessly
  -- materializes it hundreds of times for a complete weekly schedule.
  select coalesce(jsonb_object_agg(jsonb_build_array(e->>'fromLocationId',e->>'toLocationId')::text,true),'{}'::jsonb)
   into planned_valid_edges from jsonb_array_elements(source->'proximity') e
   where e->'verified'='true'::jsonb and jsonb_typeof(e->'minutes')='number'
    and (e->>'minutes')::numeric>=0 and (e->>'minutes')::numeric=trunc((e->>'minutes')::numeric)
    and nullif(e->>'provenance','') is not null;
  for planned_day,planned_stages in select * from jsonb_each(policy->'plannedClosingOwnership') loop
   if jsonb_typeof(planned_stages) is distinct from 'array' or jsonb_array_length(planned_stages) not between 1 and 8
    then raise exception 'planned closing stages must be bounded';end if;
   select min((r#>>'{shift,end}')::time),max((r#>>'{shift,end}')::time) into planned_previous,planned_last
    from jsonb_array_elements(roster) r where r->>'dayOfWeek'=planned_day and r->>'status'='working'
     and r->'vacant'='false'::jsonb and r->>'personId' is not null;
   if planned_previous is null or planned_previous<='09:45'::time then raise exception 'planned closing needs a real afternoon roster';end if;
   select jsonb_agg(code order by code) into planned_families from
    (select distinct w->>'locationCodeSnapshot' code from jsonb_array_elements(source#>'{version,assignments}') w
     where w->>'dayOfWeek'=planned_day and w#>>'{window,start}'='09:45') f;
   if planned_families is null then raise exception 'planned closing normal families missing';end if;
   -- Before the first departure every family retains its normal source owner.
   if exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') p
    join jsonb_array_elements(effective#>'{version,assignments}') w on w->'dayOfWeek'=p->'dayOfWeek'
     and w->'locationCodeSnapshot'=p->'locationCodeSnapshot'
    where p->>'dayOfWeek'=planned_day and p#>>'{window,start}'='09:45'
     and (w#>>'{window,start}')::time<planned_previous and (w#>>'{window,end}')::time>'09:45'::time
     and w->'ownerSlotId' is distinct from p->'ownerSlotId') then raise exception 'planned closing changed pre-departure ownership';end if;
   for planned_stage in select value from jsonb_array_elements(planned_stages) loop
    perform public.static_weekly_assert_exact_object(planned_stage,array['start','end','owners'],array['start','end','owners'],'planned closing stage');
    perform public.static_weekly_v3_assert_window(planned_stage-'owners','planned closing interval');
    planned_start:=(planned_stage->>'start')::time;planned_end:=(planned_stage->>'end')::time;
    if planned_start<>planned_previous or planned_end>planned_last or jsonb_typeof(planned_stage->'owners') is distinct from 'object'
     or (select jsonb_agg(k order by k) from jsonb_object_keys(planned_stage->'owners') k) is distinct from planned_families
     then raise exception 'planned closing stages must cover every family without gaps';end if;
    for planned_parent in select w from jsonb_array_elements(source#>'{version,assignments}') w
      where w->>'dayOfWeek'=planned_day and w#>>'{window,start}'='09:45' loop
     key:=planned_stage#>>array['owners',planned_parent->>'locationCodeSnapshot'];
     select r into planned_person from jsonb_array_elements(roster) r where r->>'dayOfWeek'=planned_day and r->>'slotId'=key;
     select a into planned_availability from jsonb_array_elements(source#>'{version,slotAvailability}') a
      where a->>'dayOfWeek'=planned_day and a->>'slotId'=key;
     if planned_person is null or planned_availability is null or planned_person->>'status'<>'working'
      or planned_person->>'personId' is null or planned_person->'vacant' is distinct from 'false'::jsonb
      or (planned_person#>>'{shift,start}')::time>planned_start or (planned_person#>>'{shift,end}')::time<planned_end
      or ((planned_person#>>'{lunch,start}')::time<planned_end and planned_start<(planned_person#>>'{lunch,end}')::time)
      or (planned_parent->'restrictedSlotIds') ? key
      or not ((planned_availability->'qualifications') @> (planned_parent->'requiredQualifications'))
      or exists(select 1 from jsonb_array_elements(planned_parent->'includedLocations') loc
       where (planned_availability->'restrictions') ? (loc->>'locationId'))
      then raise exception 'planned closing recipient is absent, off duty, restricted or unqualified';end if;
     if exists(select 1 from jsonb_array_elements(effective#>'{version,assignments}') w
      where w->>'dayOfWeek'=planned_day and w->'locationCodeSnapshot'=planned_parent->'locationCodeSnapshot'
       and (w#>>'{window,start}')::time<planned_end and planned_start<(w#>>'{window,end}')::time
       and w->>'ownerSlotId' is distinct from key) then raise exception 'derived closing owner differs from exact source plan';end if;
     select coalesce(sum(least((w#>>'{window,end}')::time,planned_end)-greatest((w#>>'{window,start}')::time,planned_start)),interval '0')
      into planned_coverage from jsonb_array_elements(effective#>'{version,assignments}') w
      where w->>'dayOfWeek'=planned_day and w->'locationCodeSnapshot'=planned_parent->'locationCodeSnapshot'
       and (w#>>'{window,start}')::time<planned_end and planned_start<(w#>>'{window,end}')::time;
     if planned_coverage<>planned_end-planned_start then raise exception 'derived closing responsibility has a gap or overlap';end if;
     with anchors as (
      select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
       cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0 then w->'includedLocations'
        else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
       where w->>'dayOfWeek'=planned_day and w->>'ownerSlotId'=key and w#>>'{window,start}'='09:45'
      union all select planned_availability->>'acceptedRouteAnchorLocationId' where not exists(
       select 1 from jsonb_array_elements(source#>'{version,assignments}') w
        where w->>'dayOfWeek'=planned_day and w->>'ownerSlotId'=key and w#>>'{window,start}'='09:45')
     ), targets as (select l->>'locationId' id from jsonb_array_elements(case when jsonb_array_length(planned_parent->'includedLocations')>0
       then planned_parent->'includedLocations' else jsonb_build_array(jsonb_build_object('locationId',planned_parent->'locationId')) end) l)
     select count(*) into matches from targets t where not exists(select 1 from anchors a where a.id is not null
      and (a.id=t.id or planned_valid_edges ? jsonb_build_array(a.id,t.id)::text));
     if matches<>0 then raise exception 'planned closing lacks verified directed source proximity';end if;
    end loop;
    planned_previous:=planned_end;
   end loop;
   if planned_previous is distinct from planned_last then raise exception 'planned closing must reach final staffed departure';end if;
  end loop;
 end if;
 -- OPEN may retain a stable baseline position, never a fictitious execution
 -- owner/person. Existing optimizer/document validators retain their checks.
 if exists(select 1 from jsonb_array_elements(p_authority#>'{optimizerResult,assignments}') a
  where a->>'status' in ('OPEN','REVIEW') and (a->>'slotId' is not null or a->>'personId' is not null)) then
  raise exception 'OPEN derived work may not invent execution identity'; end if;
 for day in 0..6 loop
  select count(*),count(distinct id) into matches,location_count from (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
   cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0 then w->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
   where w->>'dayOfWeek'=day::text and w#>>'{window,start}'='09:45'
  ) locations;
  if matches<>location_count then raise exception 'immutable normal template contains duplicate physical ownership'; end if;
  span:=(extract(epoch from (boundaries->>day::text)::time)/60)::int-585;
  if span<=0 then raise exception 'invalid staffed operating span'; end if;
  minute_samples:=minute_samples+span;location_samples:=location_samples+span*location_count;
 end loop;
 if receipt->'continuity' is distinct from jsonb_build_object('minuteSamples',minute_samples,'locationMinuteChecks',location_samples,
  'coverageGaps',0,'duplicateLocations',0,'staffedDepartureByDay',boundaries,
  'scope','dated real-staff handoffs and explicit vacancy OPEN responsibility until final staffed departure; lunch overlay checked separately') then
  raise exception 'shift-end continuity counters must be independently recomputed'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source_comparison public.weekly_schedule_versions%rowtype;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;
  if tg_op='INSERT' then
    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;
    return new;
  end if;
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;
  -- v3 binds a just-created v2 draft to a registered immutable source inside
  -- the same SECURITY DEFINER transaction. No other field/revision may move.
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null then
    source_comparison:=new;
    source_comparison.authority_source_id:=old.authority_source_id;
    if source_comparison is not distinct from old then return new; end if;
  end if;
  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;
  return new;
end
$function$
